// Generated by AI (UnitTest MCP)
//! Proof that a claim is arbitrated by a real Ackplane deployment, not just
//! accepted by a socket (ADR-0096, `task:727ae37b4f5a`'s PROOF requirement).
//!
//! Skipped unless `ACKPLANE_TEST_DATABASE_URL` names the gated test PostgreSQL
//! database. The test starts the real gRPC service on an ephemeral loopback
//! port and enrolls its deterministic public key itself, so it never assumes
//! an arbitrary external server already knows the corresponding test identity.
//!
//! Run against the compose topology with, e.g.:
//! ```text
//! docker compose up -d postgres
//! ACKPLANE_TEST_DATABASE_URL=postgres://ackplane:ackplane-development-only-not-for-production@127.0.0.1:5432/ackplane cargo test -p ackplane-client --test arbitration
//! ```

use ackplane_client::{
    ClaimAnswerRequest, ClaimClient, ClaimLeaseOutcome, ClaimLeaseRequest, ClaimOperation,
    ClaimParkRequest, ClaimReleaseRequest, ClaimRenewRequest,
};
use ackplane_protocol::v1::{
    claim_delegation_service_server::ClaimDelegationServiceServer, ClaimAuthentication,
};
use ackplane_server::{
    claim_service::ClaimDelegationService,
    claim_signature::claim_signing_bytes,
    claim_store::ClaimStore,
    enrollment_store::EnrollmentStore,
    signing_keys::{self, SigningKeyRecord},
};
use ed25519_dalek::{Signer, SigningKey};
use time::{format_description::well_known::Rfc3339, OffsetDateTime};
use tokio::sync::oneshot;
use tokio_postgres::NoTls;
use tokio_stream::wrappers::TcpListenerStream;
use tonic::transport::Server;

const SIGNING_KEY_ID: &str = "ackplane-client-test-key";
const NODE_ID: &str = "ackplane-client-test-node";
const TENANT_ID: &str = "ackplane-client-test-tenant";
const REPOSITORY_ID: &str = "ackplane-client-test-repository";

fn signing_key() -> SigningKey {
    SigningKey::from_bytes(&[19; 32])
}

fn authentication(
    tenant_id: &str,
    repository_id: &str,
    task_id: &str,
    owner_id: &str,
    operation: &ClaimOperation,
) -> ClaimAuthentication {
    let mut authentication = ClaimAuthentication {
        signing_key_id: SIGNING_KEY_ID.to_string(),
        node_id: NODE_ID.to_string(),
        signed_at: OffsetDateTime::now_utc().format(&Rfc3339).unwrap(),
        nonce: unique_task_id().into_bytes(),
        signature: Vec::new(),
    };
    authentication.signature = signing_key()
        .sign(&claim_signing_bytes(
            tenant_id,
            repository_id,
            task_id,
            owner_id,
            operation,
            &authentication,
        ))
        .to_bytes()
        .to_vec();
    authentication
}

fn unique_task_id() -> String {
    let nanos = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap()
        .as_nanos();
    format!("ackplane-client-arbitration-{nanos}")
}

async fn register_test_key(database_url: &str) {
    // Apply the enrollment and signing-key schemas through their production
    // owner before inserting the fixture's already-approved key.
    let enrollment_pool = ackplane_server::db_pool::build_pool(
        database_url,
        ackplane_server::db_pool::TEST_POOL_MAX_SIZE,
    )
    .expect("the test pool builds from a valid database url");
    drop(
        EnrollmentStore::connect(&enrollment_pool)
            .await
            .expect("the gated test database should accept enrollment migrations"),
    );

    let (mut client, connection) = tokio_postgres::connect(database_url, NoTls)
        .await
        .expect("the gated test database should accept a signing-key connection");
    tokio::spawn(async move {
        connection
            .await
            .expect("the signing-key fixture connection should stay healthy");
    });
    let transaction = client
        .transaction()
        .await
        .expect("the signing-key fixture should start a transaction");
    let key = signing_key();
    signing_keys::register(
        &transaction,
        &SigningKeyRecord {
            signing_key_id: SIGNING_KEY_ID.to_string(),
            tenant_id: TENANT_ID.to_string(),
            repository_id: REPOSITORY_ID.to_string(),
            node_id: NODE_ID.to_string(),
            public_key: key.verifying_key().to_bytes().to_vec(),
            public_key_fingerprint: SIGNING_KEY_ID.to_string(),
            activated_at: std::time::SystemTime::UNIX_EPOCH,
            expires_at: None,
        },
    )
    .await
    .expect("the fixture key should register through the production schema");
    transaction
        .commit()
        .await
        .expect("the fixture key should commit");
}

#[tokio::test]
async fn a_second_owner_is_rejected_while_the_first_owners_lease_is_active() {
    let Ok(database_url) = std::env::var("ACKPLANE_TEST_DATABASE_URL") else {
        println!("skipped: ACKPLANE_TEST_DATABASE_URL not set");
        return;
    };
    register_test_key(&database_url).await;
    let pool = ackplane_server::db_pool::build_pool(
        &database_url,
        ackplane_server::db_pool::TEST_POOL_MAX_SIZE,
    )
    .expect("the test pool builds from the gated database url");
    let store = ClaimStore::connect(&pool)
        .await
        .expect("the gated test database should accept claim migrations");
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
        .await
        .expect("the authenticated test service should bind loopback");
    let address = listener.local_addr().unwrap();
    let (shutdown_tx, shutdown_rx) = oneshot::channel();
    let server = tokio::spawn(async move {
        Server::builder()
            .add_service(ClaimDelegationServiceServer::new(
                ClaimDelegationService::new(store),
            ))
            .serve_with_incoming_shutdown(TcpListenerStream::new(listener), async {
                let _ = shutdown_rx.await;
            })
            .await
            .expect("the authenticated test service should run");
    });
    let endpoint = format!("http://{address}");
    let mut client = ClaimClient::connect(&endpoint)
        .await
        .expect("the in-process authenticated service should accept the connection");

    let tenant_id = TENANT_ID.to_string();
    let repository_id = REPOSITORY_ID.to_string();
    let task_id = unique_task_id();

    let granted = client
        .delegate_claim(ClaimLeaseRequest {
            tenant_id: tenant_id.clone(),
            repository_id: repository_id.clone(),
            task_id: task_id.clone(),
            owner_id: "owner-a".to_string(),
            branch: "feat/owner-a".to_string(),
            lease_seconds: 60,
            paths: vec!["src/lib.rs".to_string()],
            symbols: vec![],
            authentication: Some(authentication(
                &tenant_id,
                &repository_id,
                &task_id,
                "owner-a",
                &ClaimOperation::Delegate {
                    branch: "feat/owner-a",
                    lease_seconds: 60,
                    paths: &["src/lib.rs".to_string()],
                    symbols: &[],
                },
            )),
        })
        .await
        .expect("delegate_claim should round-trip over the wire");
    assert_eq!(granted.outcome(), ClaimLeaseOutcome::Granted);
    assert_eq!(granted.owner_id, "owner-a");

    // The real arbitration: a second, different owner racing for the same
    // task while owner-a's lease is still active must be refused by the
    // server's compare-and-swap, not merely answered by the socket.
    let rejected = client
        .delegate_claim(ClaimLeaseRequest {
            tenant_id: tenant_id.clone(),
            repository_id: repository_id.clone(),
            task_id: task_id.clone(),
            owner_id: "owner-b".to_string(),
            branch: "feat/owner-b".to_string(),
            lease_seconds: 60,
            paths: vec!["src/lib.rs".to_string()],
            symbols: vec![],
            authentication: Some(authentication(
                &tenant_id,
                &repository_id,
                &task_id,
                "owner-b",
                &ClaimOperation::Delegate {
                    branch: "feat/owner-b",
                    lease_seconds: 60,
                    paths: &["src/lib.rs".to_string()],
                    symbols: &[],
                },
            )),
        })
        .await
        .expect("delegate_claim should round-trip over the wire");
    assert_eq!(rejected.outcome(), ClaimLeaseOutcome::Rejected);

    let renewed = client
        .renew_claim(ClaimRenewRequest {
            tenant_id: tenant_id.clone(),
            repository_id: repository_id.clone(),
            task_id: task_id.clone(),
            owner_id: "owner-a".to_string(),
            lease_seconds: 120,
            authentication: Some(authentication(
                &tenant_id,
                &repository_id,
                &task_id,
                "owner-a",
                &ClaimOperation::Renew { lease_seconds: 120 },
            )),
        })
        .await
        .expect("renew_claim should round-trip over the wire");
    assert_eq!(renewed.outcome(), ClaimLeaseOutcome::Granted);
    assert_eq!(renewed.owner_id, "owner-a");

    let released = client
        .release_claim(ClaimReleaseRequest {
            tenant_id: tenant_id.clone(),
            repository_id: repository_id.clone(),
            task_id: task_id.clone(),
            owner_id: "owner-a".to_string(),
            authentication: Some(authentication(
                &tenant_id,
                &repository_id,
                &task_id,
                "owner-a",
                &ClaimOperation::Release,
            )),
        })
        .await
        .expect("release_claim should round-trip over the wire");
    assert!(released.released);

    // Once released, owner-b's identical request now succeeds: proof this
    // was a real, stateful arbiter and not a stub that always grants.
    let granted_after_release = client
        .delegate_claim(ClaimLeaseRequest {
            tenant_id: tenant_id.clone(),
            repository_id: repository_id.clone(),
            task_id: task_id.clone(),
            owner_id: "owner-b".to_string(),
            branch: "feat/owner-b".to_string(),
            lease_seconds: 60,
            paths: vec!["src/lib.rs".to_string()],
            symbols: vec![],
            authentication: Some(authentication(
                &tenant_id,
                &repository_id,
                &task_id,
                "owner-b",
                &ClaimOperation::Delegate {
                    branch: "feat/owner-b",
                    lease_seconds: 60,
                    paths: &["src/lib.rs".to_string()],
                    symbols: &[],
                },
            )),
        })
        .await
        .expect("delegate_claim should round-trip over the wire");
    assert_eq!(granted_after_release.outcome(), ClaimLeaseOutcome::Granted);
    assert_eq!(granted_after_release.owner_id, "owner-b");

    let _ = shutdown_tx.send(());
    server.await.unwrap();
}

#[tokio::test]
async fn a_parked_claim_blocks_delegate_and_only_its_owner_may_answer() {
    let Ok(database_url) = std::env::var("ACKPLANE_TEST_DATABASE_URL") else {
        println!("skipped: ACKPLANE_TEST_DATABASE_URL not set");
        return;
    };
    register_test_key(&database_url).await;
    let pool = ackplane_server::db_pool::build_pool(
        &database_url,
        ackplane_server::db_pool::TEST_POOL_MAX_SIZE,
    )
    .expect("the test pool builds from the gated database url");
    let store = ClaimStore::connect(&pool)
        .await
        .expect("the gated test database should accept claim migrations");
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
        .await
        .expect("the authenticated test service should bind loopback");
    let address = listener.local_addr().unwrap();
    let (shutdown_tx, shutdown_rx) = oneshot::channel();
    let server = tokio::spawn(async move {
        Server::builder()
            .add_service(ClaimDelegationServiceServer::new(
                ClaimDelegationService::new(store),
            ))
            .serve_with_incoming_shutdown(TcpListenerStream::new(listener), async {
                let _ = shutdown_rx.await;
            })
            .await
            .expect("the authenticated test service should run");
    });
    let endpoint = format!("http://{address}");
    let mut client = ClaimClient::connect(&endpoint)
        .await
        .expect("the in-process authenticated service should accept the connection");

    let tenant_id = TENANT_ID.to_string();
    let repository_id = REPOSITORY_ID.to_string();
    let task_id = unique_task_id();

    let granted = client
        .delegate_claim(ClaimLeaseRequest {
            tenant_id: tenant_id.clone(),
            repository_id: repository_id.clone(),
            task_id: task_id.clone(),
            owner_id: "owner-a".to_string(),
            branch: "feat/owner-a".to_string(),
            lease_seconds: 60,
            paths: vec!["src/lib.rs".to_string()],
            symbols: vec![],
            authentication: Some(authentication(
                &tenant_id,
                &repository_id,
                &task_id,
                "owner-a",
                &ClaimOperation::Delegate {
                    branch: "feat/owner-a",
                    lease_seconds: 60,
                    paths: &["src/lib.rs".to_string()],
                    symbols: &[],
                },
            )),
        })
        .await
        .expect("delegate_claim should round-trip over the wire");
    assert_eq!(granted.outcome(), ClaimLeaseOutcome::Granted);

    let parked = client
        .park_claim(ClaimParkRequest {
            tenant_id: tenant_id.clone(),
            repository_id: repository_id.clone(),
            task_id: task_id.clone(),
            owner_id: "owner-a".to_string(),
            authentication: Some(authentication(
                &tenant_id,
                &repository_id,
                &task_id,
                "owner-a",
                &ClaimOperation::Park,
            )),
        })
        .await
        .expect("park_claim should round-trip over the wire");
    assert!(parked.parked);

    // The real arbitration: a parked claim keeps its owner's exclusive hold
    // even though its lease is cleared -- a different owner's delegate must
    // still be refused, not silently granted because the lease looks
    // expired.
    let rejected = client
        .delegate_claim(ClaimLeaseRequest {
            tenant_id: tenant_id.clone(),
            repository_id: repository_id.clone(),
            task_id: task_id.clone(),
            owner_id: "owner-b".to_string(),
            branch: "feat/owner-b".to_string(),
            lease_seconds: 60,
            paths: vec!["src/lib.rs".to_string()],
            symbols: vec![],
            authentication: Some(authentication(
                &tenant_id,
                &repository_id,
                &task_id,
                "owner-b",
                &ClaimOperation::Delegate {
                    branch: "feat/owner-b",
                    lease_seconds: 60,
                    paths: &["src/lib.rs".to_string()],
                    symbols: &[],
                },
            )),
        })
        .await
        .expect("delegate_claim should round-trip over the wire");
    assert_eq!(rejected.outcome(), ClaimLeaseOutcome::Rejected);

    // Still active: a parked claim must keep colliding with an overlap
    // check, exactly like a live-leased one, or its scope would be free for
    // the taking mid-question.
    let active = client
        .list_active_claims(ackplane_client::ActiveClaimsRequest {
            tenant_id: tenant_id.clone(),
            repository_id: repository_id.clone(),
        })
        .await
        .expect("list_active_claims should round-trip over the wire");
    assert!(active.claims.iter().any(|claim| claim.task_id == task_id));

    // Only the parking owner may answer -- a different agent's answer is
    // refused rather than granting it the resumed lease.
    let wrong_answerer = client
        .answer_claim(ClaimAnswerRequest {
            tenant_id: tenant_id.clone(),
            repository_id: repository_id.clone(),
            task_id: task_id.clone(),
            owner_id: "owner-b".to_string(),
            lease_seconds: 60,
            authentication: Some(authentication(
                &tenant_id,
                &repository_id,
                &task_id,
                "owner-b",
                &ClaimOperation::Answer { lease_seconds: 60 },
            )),
        })
        .await
        .expect("answer_claim should round-trip over the wire");
    assert_eq!(wrong_answerer.outcome(), ClaimLeaseOutcome::Rejected);

    let answered = client
        .answer_claim(ClaimAnswerRequest {
            tenant_id: tenant_id.clone(),
            repository_id: repository_id.clone(),
            task_id: task_id.clone(),
            owner_id: "owner-a".to_string(),
            lease_seconds: 60,
            authentication: Some(authentication(
                &tenant_id,
                &repository_id,
                &task_id,
                "owner-a",
                &ClaimOperation::Answer { lease_seconds: 60 },
            )),
        })
        .await
        .expect("answer_claim should round-trip over the wire");
    assert_eq!(answered.outcome(), ClaimLeaseOutcome::Granted);
    assert_eq!(answered.owner_id, "owner-a");

    // Un-parked and live again: delegate should now refuse owner-b for the
    // ordinary reason (a live lease held by someone else), not because it
    // is still parked -- proof `answer` genuinely cleared `parked`.
    let rejected_after_answer = client
        .delegate_claim(ClaimLeaseRequest {
            tenant_id: tenant_id.clone(),
            repository_id: repository_id.clone(),
            task_id: task_id.clone(),
            owner_id: "owner-b".to_string(),
            branch: "feat/owner-b".to_string(),
            lease_seconds: 60,
            paths: vec!["src/lib.rs".to_string()],
            symbols: vec![],
            authentication: Some(authentication(
                &tenant_id,
                &repository_id,
                &task_id,
                "owner-b",
                &ClaimOperation::Delegate {
                    branch: "feat/owner-b",
                    lease_seconds: 60,
                    paths: &["src/lib.rs".to_string()],
                    symbols: &[],
                },
            )),
        })
        .await
        .expect("delegate_claim should round-trip over the wire");
    assert_eq!(rejected_after_answer.outcome(), ClaimLeaseOutcome::Rejected);
    assert_eq!(rejected_after_answer.owner_id, "owner-a");

    let _ = shutdown_tx.send(());
    server.await.unwrap();
}
